package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class StringUtils_indexOfAny_TriageGen0Test {

    private static final int INDEX_NOT_FOUND = -1;

    @Test
    public void testIndexOfAny_NullStr() {
        String[] searchStrs = {"a", "b"};
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny(null, searchStrs));
    }

    @Test
    public void testIndexOfAny_NullSearchStrs() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abc", null));
    }

    @Test
    public void testIndexOfAny_EmptySearchStrs() {
        String[] searchStrs = {};
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abc", searchStrs));
    }

    @Test
    public void testIndexOfAny_FoundFirst() {
        String str = "abcdef";
        String[] searchStrs = {"a", "c", "e"};
        // 'a' is at index 0
        assertEquals(0, StringUtils.indexOfAny(str, searchStrs));
    }

    @Test
    public void testIndexOfAny_FoundMiddle() {
        String str = "abcdef";
        String[] searchStrs = {"c", "e"};
        // 'c' is at index 2, 'e' is at index 4. Min is 2.
        assertEquals(2, StringUtils.indexOfAny(str, searchStrs));
    }

    @Test
    public void testIndexOfAny_FoundLast() {
        String str = "abcdef";
        String[] searchStrs = {"e", "c"};
        // 'e' is at index 4, 'c' is at index 2. Min is 2.
        assertEquals(2, StringUtils.indexOfAny(str, searchStrs));
    }

    @Test
    public void testIndexOfAny_NotFound() {
        String str = "abcdef";
        String[] searchStrs = {"z", "x"};
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny(str, searchStrs));
    }

    @Test
    public void testIndexOfAny_WithNullInArray() {
        String str = "abcdef";
        String[] searchStrs = {null, "d", null};
        // 'd' is at index 3. Nulls should be skipped.
        assertEquals(3, StringUtils.indexOfAny(str, searchStrs));
    }

    @Test
    public void testIndexOfAny_EmptyStringInArray() {
        String str = "abcdef";
        String[] searchStrs = {"", "bc"};
        // "" is found at index 0 in any string.
        assertEquals(0, StringUtils.indexOfAny(str, searchStrs));
    }

    @Test
    public void testIndexOfAny_AllNullInArray() {
        String str = "abcdef";
        String[] searchStrs = {null, null};
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny(str, searchStrs));
    }

    @Test
    public void testIndexOfAny_MultipleMatchesSameIndex() {
        String str = "abc";
        String[] searchStrs = {"a", "a"};
        assertEquals(0, StringUtils.indexOfAny(str, searchStrs));
    }

    @Test
    public void testIndexOfAny_LongerSearchString() {
        String str = "hello world";
        String[] searchStrs = {"world", "hello"};
        // "hello" is at 0, "world" is at 6. Min is 0.
        assertEquals(0, StringUtils.indexOfAny(str, searchStrs));
    }
}
